# ------------------------------------------------------------------ yardımcılar
def fmt(n) -> str:
    try:
        return f"{int(n):,}".replace(",", ".")
    except (TypeError, ValueError):
        return str(n)


def slugify(text: str) -> str:
    import re
    table = str.maketrans("çğıöşüÇĞİÖŞÜ", "cgiosucgiosu")
    return re.sub(r"[^a-z0-9]+", "-", (text or "").translate(table).lower()).strip("-")


def grp_info(name: str):
    """(kanji, renk) — jutsu alt grubu için."""
    el = ELEMENT.get(ELEMENT_GRP.get(name, ""))
    if el:
        return el[1], el[2]
    return GRP_KANJI.get(name, "術"), "#A4A8B3"


def jutsu_groups(js):
    """Kategori → alt grup listesi."""
    cats = []
    for key, label in JCAT.items():
        items = [j for j in js if j["category"] == key]
        if not items:
            continue
        groups = {}
        for j in items:
            g = j.get("grp") or label
            groups.setdefault(g, []).append(j)
        glist = []
        for g, rows in groups.items():
            kanji, color = grp_info(g)
            glist.append({"name": g, "slug": slugify(g), "kanji": kanji, "color": color, "rows": rows, "count": len(rows),
                          "learned": sum(1 for j in rows if j.get("learned_by"))})
        if key != "element":
            glist.sort(key=lambda g: -g["count"])
        cats.append({"key": key, "label": label, "kanji": JCAT_KANJI[key], "rows": items, "groups": glist, "count": len(items)})
    return cats


def ago(iso: str) -> str:
    if not iso:
        return "—"
    try:
        t = dt.datetime.fromisoformat(iso)
        if t.tzinfo is None:
            t = t.replace(tzinfo=TZ)
    except ValueError:
        return iso
    d = dt.datetime.now(TZ) - t
    s = int(d.total_seconds())
    if s < 60:
        return "az önce"
    if s < 3600:
        return f"{s // 60} dk önce"
    if s < 86400:
        return f"{s // 3600} sa önce"
    if s < 86400 * 30:
        return f"{s // 86400} gün önce"
    return t.strftime("%d.%m.%Y")


def date_tr(iso: str) -> str:
    try:
        return dt.datetime.fromisoformat(iso).strftime("%d.%m.%Y")
    except (ValueError, TypeError):
        return iso or ""


def portrait_path(cid: int):
    for ext in ("png", "jpg", "jpeg", "webp", "gif"):
        p = DATA / "portre" / f"{cid}.{ext}"
        if p.exists():
            return p
    return None


def portrait_url(c) -> str:
    return f"/portre/{c['id']}" if c.get("has_portrait") and portrait_path(c["id"]) else ""


def asset_path(key: str):
    for p in (DATA / "portre").parent.glob(f"asset_{key}.*"):
        return p
    return None


def md_to_html(text: str) -> str:
    """Çok basit biçimlendirme: '# ' başlık, boş satır paragraf, '- ' liste, **kalın**."""
    import html
    import re
    out, para, lst = [], [], []

    def flush():
        nonlocal para, lst
        if para:
            out.append("<p>" + "<br>".join(para) + "</p>")
            para = []
        if lst:
            out.append("<ul>" + "".join(f"<li>{x}</li>" for x in lst) + "</ul>")
            lst = []

    for raw in (text or "").splitlines():
        line = html.escape(raw.rstrip())
        line = re.sub(r"\*\*(.+?)\*\*", r"<strong>\1</strong>", line)
        if not line.strip():
            flush()
        elif line.startswith("# "):
            flush()
            out.append(f"<h2>{line[2:]}</h2>")
        elif line.startswith("## "):
            flush()
            out.append(f"<h3>{line[3:]}</h3>")
        elif line.startswith("- "):
            if para:
                flush()
            lst.append(line[2:])
        else:
            if lst:
                flush()
            para.append(line)
    flush()
    return "\n".join(out)


def load_snapshot():
    p = DATA / "snapshot.json"
    if p.exists():
        try:
            set_snapshot(json.loads(p.read_text(encoding="utf-8")), save=False)
        except Exception:
            pass


def set_snapshot(snap: dict, save=True):
    STATE["snap"] = snap
    STATE["by_id"] = {c["id"]: c for c in snap.get("characters", [])}
    STATE["villages"] = {v["key"]: v for v in snap.get("villages", [])}
    if save:
        (DATA / "snapshot.json").write_text(json.dumps(snap, ensure_ascii=False), encoding="utf-8")


def snap():
    return STATE["snap"]


def chars():
    return snap().get("characters", []) if snap() else []


def ranked(period: str, village: str = ""):
    rows = [c for c in chars() if c["kp"].get(period, 0) > 0 and (not village or c["village"] == village)]
    rows.sort(key=lambda c: (-c["kp"][period], c["name"]))
    return rows


templates = Jinja2Templates(env=Environment(loader=DictLoader(TEMPLATES), autoescape=True))
templates.env.filters["fmt"] = fmt
templates.env.filters["ago"] = ago
templates.env.filters["date_tr"] = date_tr
templates.env.filters["md"] = md_to_html
templates.env.globals.update(TIER_COLOR=TIER_COLOR, GROUP_LABEL=GROUP_LABEL, GROUP_KANJI=GROUP_KANJI, ELEMENT=ELEMENT,
                             JCAT=JCAT, JCAT_KANJI=JCAT_KANJI, portrait_url=portrait_url, slugify=slugify, grp_info=grp_info)


def render(request: Request, name: str, **ctx):
    s = snap()
    base = {
        "request": request, "snap": s, "server": (s or {}).get("server", {"name": "Naruto RP", "invite": "", "tagline": "Türkçe Naruto Roleplay Sunucusu"}),
        "villages": (s or {}).get("villages", []), "vmap": STATE["villages"], "path": request.url.path,
        "generated": ago((s or {}).get("generated_at", "")) if s else "",
    }
    status = ctx.pop("status_code", 200)
    base.update(ctx)
    return templates.TemplateResponse(request, name, base, status_code=status)


# ------------------------------------------------------------------ sayfalar
async def index(request: Request):
    s = snap()
    if not s:
        return render(request, "bos.html")
    by = STATE["by_id"]
    recent = [by[i] for i in s.get("recent", []) if i in by]
    top = ranked("week")[:5]
    missions = [m for m in s.get("missions", []) if m["status"] in ("open", "full")][:5]
    wanted = sorted([c for c in chars() if c["nukenin"]], key=lambda c: -c["bounty"])[:3]
    major = [v for v in s["villages"] if v["major"]]
    return render(request, "index.html", recent=recent, top=top, missions=missions, wanted=wanted, major=major, stats=s["stats"])


async def karakterler(request: Request):
    if not snap():
        return render(request, "bos.html")
    groups = []
    for g in GROUP_ORDER:
        items = sorted([c for c in chars() if c["rank_group"] == g], key=lambda c: (-TIER_ORDER.get(c["tier"], 0), -c["xp"]))
        if items:
            groups.append({"key": g, "label": GROUP_LABEL[g], "kanji": GROUP_KANJI[g], "rows": items})
    return render(request, "karakterler.html", groups=groups, total=len(chars()))


async def karakter(request: Request):
    cid = int(request.path_params["cid"])
    c = STATE["by_id"].get(cid)
    if not c:
        raise HTTPException(404)
    v = STATE["villages"].get(c["village"])
    rank_all = next((i + 1 for i, r in enumerate(ranked("all")) if r["id"] == cid), None)
    stat_total = sum(c["stats"].values())
    return render(request, "karakter.html", c=c, v=v, rank_all=rank_all, stat_total=stat_total)


async def jutsular(request: Request):
    s = snap()
    if not s:
        return render(request, "bos.html")
    js = s.get("jutsus", [])
    cats = jutsu_groups(js)
    rank_dist = {t: len([j for j in js if j["rank"] == t]) for t in "SABCDE"}
    most = sorted([j for j in js if j.get("learned_by")], key=lambda j: -len(j["learned_by"]))[:6]
    day = dt.datetime.now(TZ).timetuple().tm_yday
    featured = most[0] if most else (js[day % len(js)] if js else None)
    return render(request, "jutsular.html", cats=cats, total=len(js), rank_dist=rank_dist, most=most, featured=featured,
                  learned=s["stats"].get("learned", 0), maxdist=max(rank_dist.values() or [1]), ngroups=sum(len(c["groups"]) for c in cats),
                  search_index=[{"id": j["id"], "name": j["name"], "grp": j.get("grp", ""), "jtype": j["jtype"], "rank": j["rank"], "requirement": j.get("requirement", "")} for j in js])


async def jutsu_grup(request: Request):
    s = snap()
    if not s:
        return render(request, "bos.html")
    slug = request.path_params["slug"]
    for cat in jutsu_groups(s.get("jutsus", [])):
        for g in cat["groups"]:
            if g["slug"] == slug:
                rows = sorted(g["rows"], key=lambda j: (-TIER_ORDER.get(j["rank"], 0), j["name"]))
                return render(request, "jutsu_grup.html", cat=cat, g=g, rows=rows)
        if slugify(cat["label"]) == slug or cat["key"] == slug:
            rows = sorted(cat["rows"], key=lambda j: (-TIER_ORDER.get(j["rank"], 0), j["name"]))
            return render(request, "jutsu_grup.html", cat=cat, g=None, rows=rows)
    raise HTTPException(404)


