async def siralama(request: Request):
    s = snap()
    if not s:
        return render(request, "bos.html")
    period = request.query_params.get("donem", "week")
    if period not in ("week", "month", "all"):
        period = "week"
    village = request.query_params.get("koy", "")
    rows = ranked(period, village)
    maxkp = rows[0]["kp"][period] if rows else 1
    vtot = []
    for v in s["villages"]:
        if v["major"]:
            tot = sum(c["kp"][period] for c in chars() if c["village"] == v["key"])
            vtot.append((v, tot))
    vmax = max([t for _, t in vtot] or [1]) or 1
    return render(request, "siralama.html", rows=rows, period=period, village=village, maxkp=maxkp, vtot=vtot, vmax=vmax,
                  label={"week": "Haftalık", "month": "Aylık", "all": "Tüm Zamanlar"}[period], min_words=s["server"].get("min_words", 30))


