routes = [
    Route("/", index),
    Route("/karakterler", karakterler),
    Route("/karakter/{cid:int}", karakter),
    Route("/jutsular", jutsular),
    Route("/jutsular/{slug}", jutsu_grup),
    Route("/jutsu/{jid:int}", jutsu),
    Route("/harita-gorsel", harita_gorsel),
    Route("/api/asset/{key}", api_asset, methods=["POST"]),
    Route("/bingo-book", bingo),
    Route("/siralama", siralama),
    Route("/harita", harita),
    Route("/wiki", wiki),
    Route("/wiki/{slug}", wiki_page),
    Route("/portre/{cid:int}", portre),
    Route("/api/sync", api_sync, methods=["POST"]),
    Route("/api/portre/{cid:int}", api_portre, methods=["POST"]),
    Route("/healthz", healthz),
    Route("/static/style.css", lambda r: Response(CSS, media_type="text/css", headers={"Cache-Control": "public, max-age=86400"})),
]

import contextlib


@contextlib.asynccontextmanager
async def lifespan(app_):
    load_snapshot()
    yield


app = Starlette(routes=routes, exception_handlers={404: not_found}, lifespan=lifespan)

if __name__ == "__main__":
    import uvicorn
    uvicorn.run(app, host="0.0.0.0", port=int(os.getenv("PORT", "8000")))
